import { openDB } from 'idb';

export async function initHighScoresDB() {
  const db = await openDB('pacman-db', 1, {
    upgrade(db) {
      // Create the high_scores object store if it does not exist
      if (!db.objectStoreNames.contains('high_scores')) {
        const store = db.createObjectStore('high_scores', {
          keyPath: 'id',
          autoIncrement: true,
        });
        // Indexes for common query patterns
        store.createIndex('score_idx', 'score', { unique: false });
        store.createIndex('player_name_idx', 'player_name', { unique: false });
        store.createIndex('achieved_at_idx', 'achieved_at', { unique: false });
      }
    },
  });
  return db;
}

import { openDB } from 'idb';

export async function initSettingsDB() {
  const db = await openDB('pacman-db', 2, {
    upgrade(db, oldVersion) {
      // Upgrade from version 1 to 2 adds the settings store
      if (oldVersion < 2) {
        if (!db.objectStoreNames.contains('settings')) {
          const store = db.createObjectStore('settings', {
            keyPath: 'key',
          });
          store.createIndex('key_idx', 'key', { unique: true });
        }
      }
    },
  });
  return db;
}

